    var body: some View {
        Canvas { context, size in
            let scale = min(size.width / Self.designWidth, size.height / Self.designHeight)
            context.translateBy(
                x: (size.width - Self.designWidth * scale) / 2,
                y: (size.height - Self.designHeight * scale) / 2
            )
            context.scaleBy(x: scale, y: scale)
            context.translateBy(x: -16.7, y: 774.0)
            context.stroke(
                Self.optionGlyph, with: .color(color),
                style: StrokeStyle(lineWidth: 62.0, lineCap: .round, lineJoin: .round)
            )
            context.fill(Self.letters, with: .color(color))
        }
        .aspectRatio(Self.designWidth / Self.designHeight, contentMode: .fit)
        .accessibilityLabel("stillpane")
    }

